function fileDownload(blob,name){const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),3000);}
function text(ctx,value,x,y,width,size,lineHeight,color,weight='400'){ctx.font=`${weight} ${size}px "Microsoft YaHei",sans-serif`;ctx.fillStyle=color;let line='';for(const ch of value){if(ctx.measureText(line+ch).width>width&&line){ctx.fillText(line,x,y);y+=lineHeight;line=ch}else line+=ch}if(line){ctx.fillText(line,x,y);y+=lineHeight}return y;}
async function cardBlob(r,m,image){let im=null;try{im=new Image();im.src=image.variants.view.file;await im.decode()}catch{im=null}const canvas=document.createElement('canvas');canvas.width=1080;canvas.height=2000;function draw(){const x=canvas.getContext('2d');x.fillStyle=m.light;x.fillRect(0,0,1080,canvas.height);x.fillStyle='#fffcf5';x.fillRect(34,34,1012,canvas.height-68);x.fillStyle=m.color;x.fillRect(34,34,1012,11);let y=text(x,'与猫 AGENT  /  恋爱人格档案',76,106,925,24,36,m.color,'600');text(x,'NO. '+m.code,850,106,160,22,30,m.color);y=text(x,'我的恋爱人格是',76,y+30,928,23,38,m.color);y=text(x,m.name,70,y+75,940,80,106,m.color,'700');y=text(x,'「'+m.line+'」',76,y+4,925,28,43,m.color);y=text(x,r.primary.title,76,y+7,925,23,36,m.color);x.font='23px "Microsoft YaHei",sans-serif';let tx=76;for(const tag of m.tags){const w=x.measureText(tag).width+38;x.fillStyle=m.light;x.fillRect(tx,y+7,w,43);x.fillStyle=m.color;x.fillText(tag,tx+19,y+37);tx+=w+15}y+=80;if(im){const h=928*im.naturalHeight/im.naturalWidth;x.drawImage(im,76,y,928,h);y+=h+20;y=text(x,'我的故事切片 · 第 '+String(image.displayQuestion).padStart(2,'0')+' 幕',76,y,928,20,30,'#7c8979');}y+=23;x.fillStyle=m.color;x.fillRect(76,y,928,2);y=text(x,'恋爱里的我',76,y+48,928,21,35,m.color);y=text(x,r.initial+'  →  '+r.romanticType+(r.adjustment?'＊':''),76,y+40,928,51,68,m.color,'700');x.font='23px "Microsoft YaHei",sans-serif';for(const a of r.axes){x.fillStyle=m.color;x.fillText(a.axis+'   '+a.before+' → '+a.after+(a.adjusted?'＊':''),76,y+18);const left=365,right=978,cy=y+8;x.fillStyle=m.light;x.fillRect(left,cy-4,right-left,8);x.strokeStyle='#98a196';x.lineWidth=3;x.beginPath();x.arc(left+(a.before===window.YUMAO_COMPLETE_DATA.axes[a.axis][0]?.1:.9)*(right-left),cy,8,0,Math.PI*2);x.stroke();x.fillStyle=m.color;x.beginPath();x.arc(left+(.5+.4*a.net/a.maxWeight)*(right-left),cy,8,0,Math.PI*2);x.fill();y+=48}y+=20;y=text(x,'○ 原来的类别    ● 本局原始得分',76,y,928,19,29,'#7e8578');if(r.adjustment)y=text(x,'＊按原版游戏规则拓展一轴；原始得分保留。',76,y+5,928,19,29,'#7e8578');y=text(x,m.gift,76,y+29,928,27,44,m.color);y=text(x,'12 次选择 · 一份关于相处方式的游戏画像',76,y+20,928,20,32,'#7e8578');y=text(x,'到「与猫」看看你的恋爱人格',76,y+17,928,23,36,m.color,'600');y=text(x,'shark7755.github.io/yumao-agent/cg-showcase-complete/',76,y+3,928,18,28,'#7e8578');return y+50;}const height=draw();canvas.height=Math.ceil(height);draw();return new Promise((resolve,reject)=>canvas.toBlob(blob=>blob?resolve(blob):reject(Error('导出失败')),'image/png'));}
async function shareCard(r,m,image,trigger){const before=trigger.textContent;trigger.disabled=true;trigger.textContent='正在制作分享卡…';try{const blob=await cardBlob(r,m,image);fileDownload(blob,'与猫_恋爱人格_'+m.name+'.png');const dialog=document.createElement('dialog');dialog.className='persona-share-dialog';const url=URL.createObjectURL(blob);dialog.innerHTML=`<div class="share-preview-head"><div><b>把这份恋爱人格，留给自己。</b><p>已开始下载。手机也可以长按图片保存。</p></div><button class="icon-button" data-share-close aria-label="关闭分享卡预览">×</button></div><img class="persona-share-image" src="${url}" alt="${m.name}的恋爱人格分享卡"><div class="share-preview-actions"><button class="button-primary" data-share-download>下载分享卡</button>${navigator.canShare?.({files:[new File([blob],'与猫.png',{type:'image/png'})]})?'<button class="text-button" data-share-system>分享给朋友</button>':''}</div>`;document.body.append(dialog);dialog.showModal();document.body.classList.add('modal-open');dialog.querySelector('[data-share-close]').onclick=()=>dialog.close();dialog.querySelector('[data-share-download]').onclick=()=>fileDownload(blob,'与猫_恋爱人格_'+m.name+'.png');const system=dialog.querySelector('[data-share-system]');if(system)system.onclick=async()=>{try{await navigator.share({files:[new File([blob],'与猫_恋爱人格.png',{type:'image/png'})],title:'我的恋爱人格是'+m.name})}catch{}};dialog.addEventListener('click',e=>{if(e.target===dialog){const rect=dialog.getBoundingClientRect();if(e.clientX<rect.left||e.clientX>rect.right||e.clientY<rect.top||e.clientY>rect.bottom)dialog.close()}});dialog.addEventListener('close',()=>{document.body.classList.remove('modal-open');URL.revokeObjectURL(url);dialog.remove()},{once:true});}catch{trigger.textContent='制作失败，点击重试';return}finally{trigger.disabled=false;if(trigger.isConnected)trigger.textContent=before}}
function render(host,answers,opts={}){const c=window.YUMAO_COMPLETE_DATA,key=opts.storageKey||'yumao.play12.initial.v1',initial=YumaoComplete.cleanInitial(opts.initial||readInitial(key)),r=YumaoComplete.build(answers,initial,c);
 if(!r.ready){host.innerHTML=`<div class="complete-report"><section class="dossier-unlock"><span class="unlock-seal">${mark('compass')}</span><p class="eyebrow">YOUR LOVE PERSONALITY</p><h1>${r.finished?'你的恋爱人格，准备揭晓。':'完成十二次选择，解锁恋爱人格。'}</h1><p>${r.finished?'最后填入你认同的初始 MBTI，看看恋爱里的你有什么不同。':`已经完成 ${r.completed} / ${r.total} 幕。继续故事，把最像你的选择留下。`}</p><label for="report-initial">你的初始 MBTI</label><select id="report-initial" data-complete-initial><option value="">请选择你的类型</option>${types.map(t=>`<option${initial===t?' selected':''}>${t}</option>`).join('')}</select><button class="button-primary" data-complete-action="generate"${r.finished?'':' disabled'}>揭晓我的恋爱人格 <span>→</span></button><p class="unlock-hint" role="status"></p><p class="small-note">使用你以前测得或认同的类型，用于前后对比。</p></section></div>`;host.querySelector('[data-complete-action=generate]').onclick=()=>{const select=host.querySelector('select'),v=select.value;if(!v){select.focus();host.querySelector('.unlock-hint').textContent='先选择你的初始 MBTI，就能打开这份档案。';return}storeInitial(v,key);opts.onInitialChange?.(v);render(host,answers,{...opts,initial:v})};return r;}
 storeInitial(r.initial,key);const m=meta[r.primary.id],evidence=chooseEvidence(r,m),featured=evidence[0]||r.evidence[0],image=photo(featured),support=r.styleScores.find(s=>s.id===r.primary.id).support.length,secondary=meta[r.secondary.id];
 host.innerHTML=`<div class="complete-report dossier" data-persona="${r.primary.id}" style="--persona:${m.color};--persona-light:${m.light};--persona-accent:${m.accent}"><header class="dossier-hero cr-hero"><div class="dossier-hero-copy"><div class="dossier-eyeline"><span>与猫 · 恋爱人格档案</span><span>NO. ${m.code}</span></div><p class="dossier-reveal">十二次选择之后，你的恋爱人格是</p><h1>${m.name}</h1><p class="dossier-en">${r.primary.en.toUpperCase()} <i>/</i> ${r.primary.name}</p><p class="dossier-tagline">${m.line}</p><div class="dossier-tags">${m.tags.map(t=>`<span>${t}</span>`).join('')}</div><div class="dossier-catchphrase"><span>你的专属称号</span><strong>${esc(r.primary.title)}</strong></div></div><div class="dossier-hero-art"><div class="dossier-emblem">${mark(m.symbol)}</div><figure class="dossier-snapshot">${art(image)}<figcaption><span>你的故事切片</span><span>第 ${String(featured.questionId).padStart(2,'0')} 幕 / ${featured.optionId}</span></figcaption></figure><div class="dossier-type-stamp"><span>恋爱里的你</span><strong>${r.romanticType}${r.adjustment?'<sup>＊</sup>':''}</strong><small>从 ${r.initial} 出发</small></div></div></header><div class="dossier-toolbar"><p><span>12 / 12</span> 你的选择，已整理成档。</p><button class="persona-save" data-complete-action="card">保存我的人格卡 <span>↗</span></button></div><form class="cr-initial-editor dossier-editor" hidden><label>初始 MBTI<select>${types.map(t=>`<option${r.initial===t?' selected':''}>${t}</option>`).join('')}</select></label><div class="cr-controls"><button type="submit" class="primary">更新档案</button><button type="button" class="secondary" data-complete-action="cancel-initial">取消</button></div></form>
 <section class="dossier-evidence"><div class="dossier-section-heading"><span>01 / 有迹可循的你</span><h2>这个称号，藏在你的选择里。</h2></div><div class="dossier-evidence-grid">${evidence.slice(0,2).map(e=>`<article><span>第 ${String(e.questionId).padStart(2,'0')} 幕 <i>·</i> ${esc(e.title)}</span><p>你选择了</p><strong>${esc(e.label)}</strong></article>`).join('')}</div><p class="dossier-evidence-foot">本局 ${support} 次选择带有${r.primary.name}的倾向。${r.close?`你也带着一点${secondary.name}的色彩。`:'每次选择，都为这份画像添了一笔。'}</p></section>
 <section class="dossier-dashboard"><article class="dossier-panel"><div class="dossier-section-heading"><span>02 / 你的爱情配方</span><h2>哪一种喜欢，更像你？</h2></div>${radar(r,c)}<p class="dossier-note">各类按本局可得满分折算，不代表人格概率。</p></article><article class="dossier-panel"><div class="dossier-section-heading"><span>03 / 靠近时的变化</span><h2>同样是你，也有新一面。</h2></div><div class="cr-type dossier-type"><span><small>原来的你</small><strong>${r.initial}</strong></span><em>→</em><span><small>恋爱里的你</small><strong>${r.romanticType}${r.adjustment?'<sup>＊</sup>':''}</strong></span></div>${axes(r,c)}${r.adjustment?'<p class="dossier-note adjusted-note">＊原始类型与初始相同。沿用原版游戏规则拓展一轴，图中保留原始得分。</p>':''}<button class="dossier-edit" data-complete-action="edit-initial">修改初始 MBTI ↗</button></article></section>
 <section class="dossier-relationship"><div class="dossier-section-heading"><span>04 / 和你恋爱是什么体验</span><h2>你值得被这样理解。</h2></div><div class="dossier-relationship-grid"><article><span>你带来的心动</span><p>${m.gift}</p></article><article><span>也留一点给自己</span><p>${m.need}</p></article></div></section>
 <details class="dossier-detail"><summary><span>读懂更多的我</span><span>爱情风格解读与四轴细节 <b>＋</b></span></summary><div class="dossier-detail-body"><h2>${esc(r.primary.title)}</h2>${r.primary.intro.map(p=>`<p>${esc(p)}</p>`).join('')}${r.primary.sections.map(([h,ps])=>`<h3>${esc(h)}</h3><p>${esc(ps.join(''))}</p>`).join('')}${r.axes.map(a=>`<article class="cr-axis"><div class="cr-axis-head"><b>${a.before} → ${a.after}${a.adjusted?'＊':''}</b><span>${a.adjusted?'游戏拓展方向':a.tie?'同分保留初始':a.changed?'本局呈现不同方向':'本局与初始同向'}</span></div><h3>${esc(a.module.title)}</h3><p>${esc(a.adjusted?c.practiceCopy[a.axis+'_'+a.after]:a.module.text)}</p></article>`).join('')}</div></details>
 <section class="dossier-letter"><span>写给恋爱里的你</span><p class="dossier-letter-main">${m.line}</p><p>${esc(r.message)}</p><div><span>与猫 AGENT</span><span>${mark(m.symbol)}</span></div></section>
 <details class="cr-method dossier-detail"><summary><span>这份档案如何生成</span><span>本局选择与评分依据 <b>＋</b></span></summary><div class="dossier-detail-body">${r.evidence.map(e=>`<p><b>第 ${e.questionId} 幕 · ${esc(e.title)}</b><br>${e.optionId} · ${esc(e.label)}</p>`).join('')}<p class="dossier-note">沿用原版六类风格与 MBTI 游戏评分。风格按各类可得满分折算，同分依次比较强支持次数、支持题数和固定顺序。四轴合并主轴与辅助信号，同分保留初始；若四字母完全相同，按最小归一化净分拓展一轴并标注＊，原始分数不改动。</p>${r.axes.map(a=>`<p>${a.axis} 净分 ${a.net}/${a.maxWeight}：${a.evidence.map(e=>`第${e.questionId}幕 ${e.direction}×${e.weight}`).join('，')}</p>`).join('')}<div class="cr-controls"><button class="secondary" data-complete-action="export">导出本局记录</button><button class="secondary" data-complete-action="print">打印档案</button></div></div></details><div class="dossier-final-actions"><button class="persona-save" data-complete-action="card-footer">保存我的人格卡 <span>↗</span></button>${opts.home?'<button class="text-button" data-complete-action="home">回到故事</button>':''}</div><p class="cr-footer">这是十二次选择里的游戏画像。四个字母之外，也留一点空间给真实的自己。</p></div>`;
 const editor=host.querySelector('.cr-initial-editor');host.querySelector('[data-complete-action=edit-initial]').onclick=()=>{editor.hidden=false;editor.scrollIntoView({behavior:matchMedia('(prefers-reduced-motion:reduce)').matches?'instant':'smooth',block:'center'});editor.querySelector('select').focus({preventScroll:true})};host.querySelector('[data-complete-action=cancel-initial]').onclick=()=>editor.hidden=true;editor.onsubmit=e=>{e.preventDefault();const v=editor.querySelector('select').value;storeInitial(v,key);opts.onInitialChange?.(v);render(host,answers,{...opts,initial:v});host.scrollIntoView({block:'start',behavior:'instant'})};for(const name of ['card','card-footer']){const b=host.querySelector(`[data-complete-action=${name}]`);b.onclick=()=>shareCard(r,m,image,b)}if(opts.home)host.querySelector('[data-complete-action=home]').onclick=opts.home;host.querySelector('[data-complete-action=print]').onclick=()=>window.print();host.querySelector('[data-complete-action=export]').onclick=()=>fileDownload(new Blob([JSON.stringify(previous.resultExport(r,answers),null,2)],{type:'application/json;charset=utf-8'}),'与猫_恋爱人格档案.json');return r;
}
